import{_ as a}from"./chunks/daily-2026-08-20-skill-vs-tool-authority-figure-1.CkmyOklv.js";import{_ as o,C as i,o as s,c as n,E as r,a2 as l}from"./chunks/framework.Cm6XCzck.js";const y=JSON.parse('{"title":"An AI Agent’s Skill Is Not Its Permission: Why ‘Knows How’ Must Stay Separate from ‘May Do’","description":"","frontmatter":{"title":"An AI Agent’s Skill Is Not Its Permission: Why ‘Knows How’ Must Stay Separate from ‘May Do’","date":"2026-08-20","column":"industry-architecture","category":"daily","article_type":"project-research","edition":"research-center","research_question":"Why must an Agent runtime keep behavioral knowledge separate from tool capability, operation effects, and occurrence-scoped approval?","summary":"Playbooks teach methods, role capabilities allocate callable tools, effect policy evaluates real consequences, and one-time approval releases only one matching action. Public code and 35 targeted tests ground the four-layer model.","item_id":"MANUAL-20260820-SKILL-AUTHORITY","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-20-skill-vs-tool-authority-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"sources":["research/manual-runs/2026-08-20-guided-article-pipeline-round1/02-source-register.md","research/manual-runs/2026-08-20-guided-article-pipeline-round1/02-fact-claim-matrices.md","research/manual-runs/2026-08-20-guided-article-pipeline-round1/02-article-briefs.md","research/manual-runs/2026-08-20-guided-article-pipeline-round1/02-experiment-run-log.md","research/manual-runs/2026-08-20-guided-article-pipeline-round1/02-independent-editorial-review-round4.md","research/manual-runs/2026-08-20-guided-article-pipeline-round1/03-independent-visual-package-review.md"]},"headers":[],"relativePath":"en/industry/2026-08-20-skill-vs-tool-authority.md","filePath":"en/industry/2026-08-20-skill-vs-tool-authority.md","lastUpdated":1787377515000}'),c={name:"en/industry/2026-08-20-skill-vs-tool-authority.md"};function p(d,e,h,u,m,g){const t=i("ArticleCover");return s(),n("div",null,[r(t,{image:"/assets/covers/daily-2026-08-20-skill-vs-tool-authority-cover.png",kicker:"Industry Architecture · Project Research",title:"An AI Agent’s Skill Is Not Its Permission: Why ‘Knows How’ Must Stay Separate from ‘May Do’",summary:"Playbooks teach methods, role capabilities allocate callable tools, effect policy evaluates consequences, and one-time approval releases one matching action.",version:"MANUAL-20260820-SKILL-AUTHORITY",status:"Community Readability PASS · 2026-08-22",languageHref:"/zh/industry/2026-08-20-skill-vs-tool-authority",languageLabel:"中文"}),e[0]||(e[0]=l('<h1 id="an-ai-agent-s-skill-is-not-its-permission-why-knows-how-must-stay-separate-from-may-do" tabindex="-1">An AI Agent’s Skill Is Not Its Permission: Why “Knows How” Must Stay Separate from “May Do” <a class="header-anchor" href="#an-ai-agent-s-skill-is-not-its-permission-why-knows-how-must-stay-separate-from-may-do" aria-label="Permalink to &quot;An AI Agent’s Skill Is Not Its Permission: Why “Knows How” Must Stay Separate from “May Do”&quot;">​</a></h1><p>Give an AI agent a deployment manual, a terminal, and file-writing tools. It can now build, test, and deploy. Does that mean it may push code toward production? Of course not. The dangerous configuration error is to treat “knows how” as “has been authorized”: a release that was supposed to wait for review can enter the deployment path simply because the relevant tool is visible.</p><p>The remedy is not a longer prompt. Execution authority needs four independent gates: a playbook describes how to work, role capability decides which tool may be called, operation policy inspects the real target and side effects, and human approval releases one exact action. This article turns those gates into an implementation and audit checklist.</p><p>Think of a controlled office release. A Skill is the operating manual. A Tool is the machine that can actually change a file or run a command. Role capability is the access badge. Operation policy is the work order naming the target and consequences. Approval is the signature on this one work order. Reading the manual, reaching the machine, holding a badge, and receiving approval are four different facts.</p><table tabindex="0"><thead><tr><th>Question</th><th>Plain-language role</th><th>Engineering layer</th><th>What it decides</th></tr></thead><tbody><tr><td>How should the work be done?</td><td>operating manual</td><td>Skill / playbook</td><td>methods, steps, and checks</td></tr><tr><td>What may this role call?</td><td>access badge</td><td>role capability</td><td>eligibility to initiate a class of tool calls</td></tr><tr><td>What will this call affect?</td><td>concrete work order</td><td>operation policy</td><td>arguments, targets, paths, and side effects</td></tr><tr><td>May this occurrence proceed?</td><td>one-use sign-off</td><td>approval</td><td>one exact matching action</td></tr></tbody></table><p>A Tool is not permission and is not inherently safe. It is an effect-producing interface. A badly configured gate or an overprivileged process can still make that Tool dangerous.</p><h2 id="a-playbook-describes-behavior-not-authority" tabindex="-1">A playbook describes behavior, not authority <a class="header-anchor" href="#a-playbook-describes-behavior-not-authority" aria-label="Permalink to &quot;A playbook describes behavior, not authority&quot;">​</a></h2><p>A playbook is the right place for a workflow, checklist, or role-specific method. A developer playbook might say: locate the call site, make a narrow patch, run the relevant tests, and explain the evidence. That improves execution discipline. It does not grant write access.</p><p>This article uses the open-source multi-agent governance runtime CodeFlowMu as its engineering case. CodeFlowMu represents this layer as Agent Playbook Skills. Its <a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/packages/codeflowmu-runtime/src/skills/SkillContextRouter.ts" target="_blank" rel="noreferrer"><code>SkillContextRouter</code></a> selects playbooks from role, intent, and task signals. Ordinary tasks receive a small matched set instead of the entire catalog. Governed product-planning tasks are an explicit exception: they load the required minimum set, so it would be inaccurate to claim that the router always loads at most three skills.</p><p>The separation yields two benefits. Irrelevant guidance does not consume every prompt, and the runtime can record why a playbook was selected. But the boundary remains firm:</p><blockquote><p>Auto-loaded guidance is neither execution authorization nor evidence that execution succeeded.</p></blockquote><p>A prompt can tell an agent to test before committing. It cannot prove a test ran, and it cannot authorize a remote push.</p><p><img src="'+a+`" alt="Four layers separately answer how, what may be called, who is affected, and whether this occurrence is approved; approval grants only one controlled execution attempt"></p><p><em>Figure 1. Four separate authority responsibilities. Source: author synthesis from the pinned CodeFlowMu implementation and MCP/NIST boundaries; this is not a universal FCoP or MCP field format.</em></p><h2 id="a-role-capability-allows-a-class-of-calls" tabindex="-1">A role capability allows a class of calls <a class="header-anchor" href="#a-role-capability-allows-a-class-of-calls" aria-label="Permalink to &quot;A role capability allows a class of calls&quot;">​</a></h2><p>The next layer is the callable tool set. CodeFlowMu canonicalizes a tool identifier and checks whether the current role owns that capability.</p><p>The public implementation distinguishes, for example, between workers that may read coordination artifacts and submit reports, project managers that may create downstream tasks, administrators that own approval and archive operations, and evaluators whose native tools are limited to reads.</p><p>These roles are not theatrical prompt personas. They allocate decision rights that prompt text should not be able to rewrite.</p><p>The comment on <a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/packages/codeflowmu-runtime/src/registry/RoleToolCapabilityGate.ts" target="_blank" rel="noreferrer"><code>RoleToolCapabilityGate</code></a> is deliberately narrow: it is an exact role/tool gate and does not inspect command text or effects.</p><p>Consider two calls:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>write_file(&quot;D:/project-a/src/app.ts&quot;)</span></span>
<span class="line"><span>write_file(&quot;D:/another-project/secrets.txt&quot;)</span></span></code></pre></div><p>The tool name is identical. The first target may be inside the active task boundary; the second escapes the project. A tool allowlist cannot distinguish them.</p><p>The role gate can answer “may this role initiate this kind of call?” It cannot answer “are these parameters and their real-world effects acceptable?”</p><h2 id="operation-policy-must-inspect-targets-and-effects" tabindex="-1">Operation policy must inspect targets and effects <a class="header-anchor" href="#operation-policy-must-inspect-targets-and-effects" aria-label="Permalink to &quot;Operation policy must inspect targets and effects&quot;">​</a></h2><p>Risk lives in arguments. A useful operation policy needs to determine whether the call reads, writes, deletes, publishes, or controls a process; whether its target is inside the active project; whether it changes persistent state; whether it writes to an external system; whether it changes governance or privilege; and whether the effect is reversible.</p><p>CodeFlowMu’s <a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/packages/codeflowmu-runtime/src/approval/UnifiedOperationPolicy.ts" target="_blank" rel="noreferrer"><code>UnifiedOperationPolicy</code></a> constructs operation facts and then returns one of two routes: allow, or require approval. A role’s possession of <code>write_file</code> does not automatically authorize a cross-project write or a mutation of formal governance artifacts.</p><p>The external standards point in the same direction. MCP is an open protocol for connecting model applications to tools and data. Its <a href="https://modelcontextprotocol.io/specification/2025-03-26/index" target="_blank" rel="noreferrer">security and trust guidance</a> warns that tools create arbitrary data-access and code-execution paths, and that tool descriptions and annotations should not be trusted by default. Hosts need consent and authorization controls. The <a href="https://modelcontextprotocol.io/specification/2025-06-18/basic/authorization" target="_blank" rel="noreferrer">MCP authorization specification</a> separately defines HTTP authorization, resource binding, insufficient permissions, and token protections.</p><p>Those documents establish that connectivity is not authorization. They do not define CodeFlowMu’s role matrix or decide whether a local path crosses the active project boundary. That remains an application-runtime responsibility.</p><h2 id="approval-should-bind-one-operation-not-create-a-permanent-pass" tabindex="-1">Approval should bind one operation, not create a permanent pass <a class="header-anchor" href="#approval-should-bind-one-operation-not-create-a-permanent-pass" aria-label="Permalink to &quot;Approval should bind one operation, not create a permanent pass&quot;">​</a></h2><p>“Allow terminal” is too broad to be a safe approval record. The decision should bind a specific actor, task, tool, target, effect set, and operation fingerprint:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">DEV-01</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">task</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">TASK-042</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">write_file</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">D:/project-a/src/app.ts</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">operation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">write</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">effects</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  persistent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  external</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">fingerprint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sha256:...</span></span></code></pre></div><p>This is an explanatory projection of the CodeFlowMu implementation, not an MCP or FCoP standard schema. The principle matters more than the field names: if the arguments change, an old approval must not authorize a different action.</p><p>The current <code>UnifiedOperationPolicy</code> can prepare an approval request with a target, effects, and an operation fingerprint, and it declares an original-agent retry strategy. Approval still means only “this attempt is allowed.” A remote system can reject it, the network can fail, and tests can still fail. Execution evidence must establish the outcome.</p><h3 id="approval-must-bind-the-world-that-was-reviewed" tabindex="-1">Approval must bind the world that was reviewed <a class="header-anchor" href="#approval-must-bind-the-world-that-was-reviewed" aria-label="Permalink to &quot;Approval must bind the world that was reviewed&quot;">​</a></h3><p>An argument fingerprint is not enough. After an administrator approves a write to <code>app.ts</code> but before execution, another process may change the file. A minimum approval contract should bind the actor, role, task, project, tool, full arguments, canonical target, a pre-state digest such as Git HEAD or a file hash, an expiry, and a random one-use execution credential.</p><p>CodeFlowMu’s current <code>OperationApprovalService</code> has a request digest, expiry, random one-time execution token, and available/consumed authorization state. Thirteen additional targeted service tests passed for expiry, invalid tokens, stale requests, and concurrent single consumption. A specialized workspace adapter can include Git HEAD and file snapshots, but that does not establish uniform pre-state binding across every tool path. The supported conclusion is narrower: expiry and single consumption have executable evidence; TOCTOU protection still requires executor-by-executor verification.</p><p>There need not be a field literally named <code>nonce</code>. A random single-use execution token supplies replay resistance. A network retry should preserve the same request identity; changed parameters or pre-state require a new approval.</p><h3 id="these-gates-are-not-an-operating-system-sandbox" tabindex="-1">These gates are not an operating-system sandbox <a class="header-anchor" href="#these-gates-are-not-an-operating-system-sandbox" aria-label="Permalink to &quot;These gates are not an operating-system sandbox&quot;">​</a></h3><p>Role capability resembles coarse RBAC, while operation policy resembles attribute- and effect-aware authorization. MCP connects tools but does not replace either layer. None of them substitutes for a low-privilege process, filesystem controls, egress restrictions, or a container sandbox.</p><p>Static path and command parsing also has limits. Wrappers, symlinks, composed shell expressions, and runtime-generated targets can defeat lexical assumptions. High-risk work should use controlled executors plus system-level confinement. The tests in this article do not establish a general CodeFlowMu container sandbox or resistance to arbitrary command obfuscation.</p><p>NIST SP 800-171 Rev. 3 supplies a broader security basis. Least privilege applies to users and processes acting for users; privileged functions should be restricted and logged. It is not an agent-specific architecture, but it reinforces the separation between assigning privilege, invoking privilege, and auditing what happened.</p><h2 id="where-tmpa-fcop-and-codeflowmu-fit" tabindex="-1">Where TMPA, FCoP, and CodeFlowMu fit <a class="header-anchor" href="#where-tmpa-fcop-and-codeflowmu-fit" aria-label="Permalink to &quot;Where TMPA, FCoP, and CodeFlowMu fit&quot;">​</a></h2><p>The three project names are easy to confuse, so the responsibilities should be stated before using them as shorthand:</p><table tabindex="0"><thead><tr><th>Layer</th><th>Owns</th><th>Does not own</th></tr></thead><tbody><tr><td>TMPA, the governance model</td><td>roles, authority, separation of duties, evidence and acceptance boundaries</td><td>tool registration or process execution</td></tr><tr><td>FCoP, the file coordination protocol</td><td>task, report, issue, and review envelopes and lifecycle facts</td><td>host authorization for terminal commands</td></tr><tr><td>CodeFlowMu, the runtime product</td><td>playbook routing, capability checks, operation policy, approval routing, and agent execution</td><td>automatic conversion of an attempt into business success</td></tr></tbody></table><p>In short: TMPA defines the governance semantics, FCoP defines shared coordination artifacts, and CodeFlowMu enforces runtime decisions.</p><h2 id="what-35-targeted-passing-tests-establish—and-what-they-do-not" tabindex="-1">What 35 targeted passing tests establish—and what they do not <a class="header-anchor" href="#what-35-targeted-passing-tests-establish—and-what-they-do-not" aria-label="Permalink to &quot;What 35 targeted passing tests establish—and what they do not&quot;">​</a></h2><p>For this article, we checked out CodeFlowMu Open commit <code>ed5634c718b9e238c44bb70851020c9793546fe6</code> in an isolated worktree. The playbook, tool-mount, role-capability, and operation-policy sets passed <strong>22 of 22</strong> tests. A targeted approval-service set passed <strong>13 of 13</strong>, for <strong>35 passing tests</strong> in total.</p><p>The tests cover unrelated chat loading no playbooks; Chinese and English task signals routing to research playbooks; role-specific routing; same-project writes being allowed while cross-project writes are approval-routed; formal governance mutations being approval-routed; an evaluator being denied a write capability; approval expiry and invalid tokens; stale request digests; concurrent single consumption; and a resumed original-agent session consuming one matching authorization.</p><p>The run also exposed a limit that belongs in the public article. The older <code>MCPInjector</code> stub records proposed mounts but starts no subprocess. <code>mode=&#39;live&#39;</code> deliberately throws a not-implemented error. This article therefore does not present it as a live dynamic MCP mounting system. The evidence supports context routing, role capability checks, and operation policy—not every planned MCP lifecycle feature.</p><p>Passing 35 targeted tests is not a penetration test or third-party security certification. The runs do not establish uniform file-snapshot binding, complex command parsing, symlink resistance, container isolation, or arbitrary third-party MCP safety. Dependency installation also reported six audit findings that require separate review. A green functional suite should not be repackaged as a supply-chain security conclusion.</p><h2 id="three-regression-cases-worth-keeping" tabindex="-1">Three regression cases worth keeping <a class="header-anchor" href="#three-regression-cases-worth-keeping" aria-label="Permalink to &quot;Three regression cases worth keeping&quot;">​</a></h2><h3 id="guidance-must-not-grant-authority" tabindex="-1">Guidance must not grant authority <a class="header-anchor" href="#guidance-must-not-grant-authority" aria-label="Permalink to &quot;Guidance must not grant authority&quot;">​</a></h3><p>Load a code-fix playbook for a QA role without granting write tools. The role may produce a recommendation, but it must not land a patch.</p><h3 id="one-tool-two-targets-two-decisions" tabindex="-1">One tool, two targets, two decisions <a class="header-anchor" href="#one-tool-two-targets-two-decisions" aria-label="Permalink to &quot;One tool, two targets, two decisions&quot;">​</a></h3><p>Have a developer write once inside the active project and once into a neighboring project. The second call must not reuse the first decision merely because the tool name matches.</p><h3 id="approval-must-not-become-completion" tabindex="-1">Approval must not become completion <a class="header-anchor" href="#approval-must-not-become-completion" aria-label="Permalink to &quot;Approval must not become completion&quot;">​</a></h3><p>Approve a remote publication attempt, then make the remote service fail. The approval remains “authorized,” execution becomes “failed,” and the task must not become accepted.</p><h2 id="a-practical-review-checklist" tabindex="-1">A practical review checklist <a class="header-anchor" href="#a-practical-review-checklist" aria-label="Permalink to &quot;A practical review checklist&quot;">​</a></h2><p>For every agent capability, ask:</p><ol><li>Where is the method stored, and when is it loaded?</li><li>Which roles can see and call the tool?</li><li>Are aliases reduced to one canonical tool identifier?</li><li>Who resolves paths, URLs, repositories, and target objects in the arguments?</li><li>How are cross-project writes, external effects, deletion, publication, and governance changes escalated?</li><li>Does approval bind the task, target, and operation fingerprint?</li><li>Can an approved operation fail without the task becoming complete?</li><li>Are playbook selection, denial, approval, and execution recorded separately?</li></ol><p>The following is target audit logic, not a current CodeFlowMu API:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>role cannot call tool                       → deny</span></span>
<span class="line"><span>target or effects cannot be resolved        → stop or use a controlled executor</span></span>
<span class="line"><span>bounded low-risk action                     → allow an attempt</span></span>
<span class="line"><span>approval required                           → bind request digest, pre-state, and expiry</span></span>
<span class="line"><span>expired, consumed, or changed pre-state     → invalidate old approval</span></span>
<span class="line"><span>exact approval match                        → consume once, execute under confinement, record evidence</span></span>
<span class="line"><span>execution fails                             → remain failed; authorization is not completion</span></span></code></pre></div><p>A small read-only assistant may combine implementation components, but it should preserve these semantic distinctions. Otherwise, as the system grows, it will lose the ability to answer a basic governance question: did this action occur because the agent had learned a method, or because the organization had authorized it?</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>Skills package method. Tools expose execution. Capabilities allocate role authority. Approval decides a specific risk. The four concepts are related, but none substitutes for another.</p><blockquote><p>Knowing how proves that an agent has a method. Only a valid role capability, an acceptable effect evaluation, and a matching approval give it an opportunity to execute this action.</p></blockquote><p>This architecture does not make the model smarter. It preserves control when the model’s judgment is wrong.</p><h2 id="primary-sources" tabindex="-1">Primary sources <a class="header-anchor" href="#primary-sources" aria-label="Permalink to &quot;Primary sources&quot;">​</a></h2><ol><li><a href="https://modelcontextprotocol.io/specification/2025-03-26/index" target="_blank" rel="noreferrer">Model Context Protocol: Security and Trust &amp; Safety</a></li><li><a href="https://modelcontextprotocol.io/specification/2025-06-18/basic/authorization" target="_blank" rel="noreferrer">Model Context Protocol: Authorization</a></li><li><a href="https://nvlpubs.nist.gov/nistpubs/SpecialPublications/800-171r3/NIST.SP.800-171r3.html" target="_blank" rel="noreferrer">NIST SP 800-171 Rev. 3</a></li><li><a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/packages/codeflowmu-runtime/src/skills/SkillContextRouter.ts" target="_blank" rel="noreferrer">CodeFlowMu SkillContextRouter, pinned commit</a></li><li><a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/packages/codeflowmu-runtime/src/registry/RoleToolCapabilityGate.ts" target="_blank" rel="noreferrer">CodeFlowMu RoleToolCapabilityGate, pinned commit</a></li><li><a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/packages/codeflowmu-runtime/src/approval/UnifiedOperationPolicy.ts" target="_blank" rel="noreferrer">CodeFlowMu UnifiedOperationPolicy, pinned commit</a></li><li><a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/packages/codeflowmu-runtime/src/approval/OperationApprovalService.ts" target="_blank" rel="noreferrer">CodeFlowMu OperationApprovalService, pinned commit</a></li><li><a href="https://github.com/joinwell52-AI/CodeFlowMu-open/blob/ed5634c718b9e238c44bb70851020c9793546fe6/packages/codeflowmu-runtime/src/approval/WorkspaceOperationApproval.ts" target="_blank" rel="noreferrer">CodeFlowMu WorkspaceOperationApproval, pinned commit</a></li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/ae27de71b1a8809c2bd69acedc1482570d55a322/docs/public/releases/tmpa/v1.0/artifacts/tmpa-core-specification-s1.0-zh.md" target="_blank" rel="noreferrer">TMPA Core Specification S1.0, pinned commit</a></li><li><a href="https://github.com/joinwell52-AI/FCoP/blob/a859e6747fe6e5e2d686e0114c77774726d7f748/spec/fcop-v3-spec.zh.md" target="_blank" rel="noreferrer">FCoP v3 Chinese specification, pinned commit</a></li></ol><p>Accessed 2026-08-20.</p>`,70))])}const k=o(c,[["render",p]]);export{y as __pageData,k as default};
